#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

CF_BIN="${CF_BIN:-$HOME/.local/bin/cloudflared}"
CF_DIR="$HOME/.cloudflared"
CF_CONFIG="$CF_DIR/config.yml"
UNIT_DIR="$HOME/.config/systemd/user"
UNIT_FILE="$UNIT_DIR/cloudflared-pochi.service"
TUNNEL_NAME="pochi-gateway"
APP_PORT="8000"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

if [[ ! -x "$CF_BIN" ]]; then
  if command -v cloudflared >/dev/null 2>&1; then CF_BIN="$(command -v cloudflared)"
  else printf '\ncloudflared tidak ditemukan. Pasang dulu:\n  mkdir -p ~/.local/bin && curl -L -o ~/.local/bin/cloudflared https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64 && chmod +x ~/.local/bin/cloudflared\n\n' >&2; exit 1; fi
fi

banner "Pochi Gateway di Cloudflare Tunnel + Access"

stage "Prasyarat"
say "Wizard ini membuka Pochi Gateway ke internet lewat satu hostname, lalu mengunci"
say "hostname itu dengan login email. Port 8000 tetap hanya mendengar di 127.0.0.1."
printf '\n'
say "cloudflared : $("$CF_BIN" --version 2>/dev/null | head -1)"
if [[ -d "$REPO_ROOT/frontend/dist" ]]; then
  say "frontend/dist : ada (build produksi)"
else
  warn "frontend/dist belum ada — jalankan: cd frontend && npm run build"
fi
if curl -fsS "http://127.0.0.1:$APP_PORT/health" >/dev/null 2>&1; then
  say "backend : $(curl -fsS "http://127.0.0.1:$APP_PORT/health")"
else
  warn "backend belum menjawab di 127.0.0.1:$APP_PORT — jalankan: systemctl --user restart pochi-gateway"
fi
if grep -q '^POCHI_SEED_DEMO=false' "$REPO_ROOT/.env" 2>/dev/null; then
  say "seed demo : mati"
else
  warn ".env belum mematikan POCHI_SEED_DEMO — tambahkan POCHI_SEED_DEMO=false"
fi
printf '\n'
pause "Semua siap? Enter untuk lanjut ke login Cloudflare."

stage "Login Cloudflare"
say "Perintah berikut membuka browser. Di sana pilih zone (domain) milikmu, lalu Authorize."
step "Terminal ini akan menunggu sampai kamu selesai di browser."
printf '\n'
if [[ -f "$CF_DIR/cert.pem" ]]; then
  say "cert.pem sudah ada di $CF_DIR — login dilewati."
else
  "$CF_BIN" tunnel login || warn "login belum selesai; jalankan ulang wizard kapan saja"
fi
printf '\n'
if [[ -f "$CF_DIR/cert.pem" ]]; then
  say "✓ cert.pem tersimpan: $(basename "$CF_DIR/cert.pem")"
else
  warn "cert.pem belum ada. Tanpa itu tunnel tidak bisa dibuat."
fi
pause "Lanjut?"

stage "Hostname publik"
say "Pakai domain yang sudah aktif di Cloudflare (nameserver-nya sudah pindah)."
printf '\n'
ask DOMAIN "Domain (contoh: example.com):" || DOMAIN=""
DOMAIN="${DOMAIN#http://}"; DOMAIN="${DOMAIN#https://}"; DOMAIN="${DOMAIN%%/*}"
if [[ -z "${DOMAIN:-}" ]]; then warn "domain wajib diisi — jalankan ulang wizard"; exit 1; fi
ask SUBDOMAIN "Subdomain (kosongkan untuk 'gw'):" || SUBDOMAIN=""
SUBDOMAIN="${SUBDOMAIN%%.*}"
[[ -z "${SUBDOMAIN:-}" ]] && SUBDOMAIN="gw"
HOSTNAME="${SUBDOMAIN}.${DOMAIN}"
printf '\n'
say "URL publik nanti: https://$HOSTNAME"
pause "Benar? Enter untuk membuat tunnel."

stage "Buat tunnel"
say "Tunnel '$TUNNEL_NAME' menghubungkan Cloudflare ke 127.0.0.1:$APP_PORT di mesin ini."
printf '\n'
mkdir -p "$CF_DIR"
if "$CF_BIN" tunnel list 2>/dev/null | grep -qw "$TUNNEL_NAME"; then
  say "tunnel '$TUNNEL_NAME' sudah ada, dipakai ulang."
else
  "$CF_BIN" tunnel create "$TUNNEL_NAME"
fi
TUNNEL_ID="$(ls "$CF_DIR"/*.json 2>/dev/null | head -1 | xargs -r -n1 basename | sed 's/\.json$//')"
if [[ -z "${TUNNEL_ID:-}" ]]; then
  warn "credentials tunnel tidak ditemukan di $CF_DIR"
  exit 1
fi
cat > "$CF_CONFIG" <<CONF
tunnel: $TUNNEL_NAME
credentials-file: $CF_DIR/$TUNNEL_ID.json

ingress:
  - hostname: $HOSTNAME
    service: http://127.0.0.1:$APP_PORT
  - service: http_status:404
CONF
chmod 600 "$CF_CONFIG"
say "✓ tulis $CF_CONFIG (tunnel id ${TUNNEL_ID:0:8}…)"
pause "Lanjut ke DNS?"

stage "Arahkan DNS"
say "Ini membuat CNAME $HOSTNAME → ${TUNNEL_ID:0:8}….cfargotunnel.com di zone-mu."
printf '\n'
if "$CF_BIN" tunnel route dns "$TUNNEL_NAME" "$HOSTNAME"; then
  say "✓ DNS diarahkan"
else
  warn "gagal membuat DNS. Biasanya karena zone belum ada di cert.pem (ulangi stage login)."
fi
pause "Lanjut ke penguncian akses?"

stage "Kunci dengan Cloudflare Access"
say "Sampai sini hostname sudah publik. Stage ini yang membuat hanya kamu yang bisa masuk."
printf '\n'
ask ACCESS_EMAIL "Email yang boleh masuk:" || { warn "email wajib"; exit 1; }
open_url "https://one.dash.cloudflare.com"
step "Menu Access → Applications → Add an application → Self-hosted."
step "Application name: Pochi Gateway. Domain: $HOSTNAME (tanpa https://)."
step "Session duration: 24 hours."
step "Add policy → Action Allow → Include → Emails → isi: $ACCESS_EMAIL"
step "Save. Login method: One-time PIN (aktif default di Settings → Authentication)."
printf '\n'
note "Kalau ada sistem luar yang memanggil webhook workflow (/api/v1/hooks/…),"
note "tambahkan path itu sebagai aplikasi Access terpisah dengan policy Bypass."
printf '\n'
confirm "Aplikasi Access sudah dibuat dan disimpan?" || warn "selesaikan dulu, lalu jalankan ulang wizard"

stage "Jalankan sebagai service"
say "cloudflared dijalankan sebagai user service, otomatis hidup lagi setelah reboot."
printf '\n'
mkdir -p "$UNIT_DIR"
cat > "$UNIT_FILE" <<UNIT
[Unit]
Description=Cloudflare Tunnel untuk Pochi Gateway ($HOSTNAME)
After=network-online.target pochi-gateway.service
Wants=network-online.target

[Service]
Type=simple
ExecStart=$CF_BIN tunnel --config $CF_CONFIG run $TUNNEL_NAME
Restart=always
RestartSec=5

[Install]
WantedBy=default.target
UNIT
systemctl --user daemon-reload
systemctl --user enable --now cloudflared-pochi.service >/dev/null 2>&1 || warn "enable gagal, cek: systemctl --user status cloudflared-pochi"
loginctl enable-linger "$USER" >/dev/null 2>&1 || warn "enable-linger gagal — service hanya hidup selama kamu login"
say "✓ tulis $UNIT_FILE"
printf '\n'
say "Menunggu tunnel + DNS siap…"
code="000"
for _ in $(seq 1 20); do
  sleep 3
  code="$(curl -s -o /dev/null -w '%{http_code}' --max-time 8 "https://$HOSTNAME/health" || true)"
  [[ "$code" != "000" ]] && break
done
case "$code" in
  302|301) say "✓ https://$HOSTNAME menjawab $code — diarahkan ke login Access. Gate aktif." ;;
  200) warn "https://$HOSTNAME menjawab 200 tanpa login. Access belum aktif — ulangi stage 6." ;;
  000) warn "belum ada jawaban. Cek: systemctl --user status cloudflared-pochi" ;;
  *) warn "https://$HOSTNAME menjawab $code. Cek log: journalctl --user -u cloudflared-pochi -n 50" ;;
esac
printf '\n'
say "Setelah login Access, halaman Pochi akan meminta admin token seperti biasa."
say "Token ada di: $REPO_ROOT/data/admin_token"

finish
}

run_wizard "$@"; exit
